import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.yntlMcNk.js";var o=JSON.parse(`{"title":"Kataloge","description":"","frontmatter":{"title":"Kataloge","covers":{"screens":["SCR-020","SCR-028"],"stories":["US-046","US-047","US-049"]}},"headers":[],"relativePath":"de/usage/catalogs.md","filePath":"de/usage/catalogs.md"}`),s={name:`de/usage/catalogs.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="kataloge" tabindex="-1">Kataloge <a class="header-anchor" href="#kataloge" aria-label="Permalink to “Kataloge”">​</a></h1><p>Ein Katalog ist eine wiederverwendbare Tabellenansicht des Repositorys. Er zeigt die Entitäten eines Entitätstyps als Zeilen. Du brauchst die Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>), um Kataloge zu sehen und persönliche anzulegen; geteilte Kataloge brauchen <code>catalog:manage</code> (Rolle <code>enterprise-architect</code>).</p><h2 id="katalog-anlegen" tabindex="-1">Katalog anlegen <a class="header-anchor" href="#katalog-anlegen" aria-label="Permalink to “Katalog anlegen”">​</a></h2><ol><li><p>Wähle <em>Kataloge</em> in der Kopfzeile, dann <em>Neuer Katalog</em>.</p></li><li><p>Fülle den Dialog <em>Neuer Katalog</em> aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>Pflicht; eindeutig in der Instanz, unabhängig von Groß- und Kleinschreibung</td></tr><tr><td>Beschreibung</td><td>optional, bis zu 1000 Zeichen</td></tr><tr><td>Primärer Entitätstyp</td><td>Pflicht; seine Entitäten werden die Zeilen der Tabelle</td></tr><tr><td>Sichtbarkeit</td><td><em>Geteilt</em>: für alle Benutzer der Instanz sichtbar (braucht die Berechtigung, Kataloge zu verwalten); <em>Persönlich</em>: nur für dich sichtbar</td></tr><tr><td>Standard-Verknüpfungsmodus</td><td><em>Zusammengefasst</em>: eine Zeile pro Entität, verknüpfte Entitäten in einer Zelle; <em>Zeilen</em>: eine Zeile pro verknüpfter Entität. Gilt für später hinzugefügte Joins</td></tr></tbody></table></li></ol>`,4),i(d,{name:`catalog-create`,alt:`Dialog Neuer Katalog mit Name, Beschreibung, Entitätstyp und Sichtbarkeit`}),o[1]||=t(`<ol start="3"><li>Wähle <em>Katalog anlegen</em>. Der neue Katalog öffnet sich.</li></ol><p>Ist der Name schon vergeben, sagt dir das der Dialog; wähle einen anderen Namen. Ohne die Berechtigung, Kataloge zu verwalten, ist <em>Geteilt</em> nicht wählbar.</p><h2 id="katalog-durchsehen" tabindex="-1">Katalog durchsehen <a class="header-anchor" href="#katalog-durchsehen" aria-label="Permalink to “Katalog durchsehen”">​</a></h2><p>Die Liste <em>Kataloge</em> zeigt jeden Katalog, den du sehen darfst, markiert mit <em>Geteilt</em> oder <em>Persönlich</em>. Öffne einen, um seine Tabelle zu sehen:</p>`,4),i(d,{name:`catalogs`,alt:`Liste der Kataloge`}),i(d,{name:`catalog-table`,alt:`Tabelle eines Katalogs mit Anwendungskomponenten`}),o[2]||=t(`<ul><li>Namen von Entitätstypen, Spaltenköpfe und Werte von Enum-Eigenschaften erscheinen in deiner Sprache, wo deine Organisation sie übersetzt hat (siehe <a href="./login#your-profile">Dein Profil</a>).</li><li>Solange keine Spalten konfiguriert sind (siehe <a href="#configure-columns">Spalten konfigurieren</a>), zeigt die Tabelle die Spalten <em>Name</em> und – wenn der Entitätstyp die Eigenschaft <em>Status</em> hat – <em>Status</em>.</li><li>Werte einer Aufzählungs-Eigenschaft wie <em>Status</em> werden in der Reihenfolge der Werte sortiert, nicht alphabetisch; Einträge ohne Wert kommen zuletzt.</li><li>Klicke auf einen Spaltenkopf, um zu sortieren: aufsteigend, absteigend und zurück zur Standardreihenfolge.</li><li>Die Tabelle zeigt 50 Einträge pro Seite; mit der Seitennavigation unter der Tabelle wechselst du zwischen den Seiten.</li><li>Sortierung und Seite sind Teil der Adresse der Seite. Zurücknavigation, Neuladen oder ein geteilter Link stellen dieselbe Ansicht wieder her; ungültige Werte in der Adresse werden ignoriert, und die erste Seite wird in der Standardreihenfolge gezeigt.</li><li>Hat der Entitätstyp noch keine Entitäten, zeigt die Tabelle <em>Keine Einträge gefunden</em>.</li><li>Den persönlichen Katalog einer anderen Person kannst du nicht öffnen; er verhält sich wie ein Katalog, den es nicht gibt (<em>Katalog nicht gefunden</em>).</li></ul><p>Über die API liefert <code>GET /catalogs/{id}/query</code> dieselben Zeilen mit den Parametern <code>page</code> (ab 0), <code>pageSize</code> (1–200, Standard 50) und <code>sort</code> (<code>{field}:{asc|desc}</code>).</p><h2 id="configure-columns" tabindex="-1">Spalten konfigurieren <a class="header-anchor" href="#configure-columns" aria-label="Permalink to “Spalten konfigurieren”">​</a></h2><p>Du bestimmst, welche Attribute ein Katalog zeigt, in welcher Reihenfolge und unter welcher Überschrift. Ein geteilter Katalog verlangt die Berechtigung, Kataloge zu verwalten (<code>catalog:manage</code>, Rolle <code>enterprise-architect</code>); deinen eigenen persönlichen Katalog konfigurierst du selbst.</p><ol><li>Öffne den Katalog und wähle <em>Spalten konfigurieren</em>.</li><li>Der Dialog listet alle Attribute des Entitätstyps: die Felder <em>Name</em>, <em>Beschreibung</em>, <em>Externe ID</em>, <em>Angelegt</em>, <em>Geändert</em> und <em>Version</em> sowie alle Eigenschaften, die dem Entitätstyp zugeordnet sind, auch die geerbten.</li><li>Pro Zeile: <ul><li><em>Sichtbar</em> blendet die Spalte ein oder aus. Eine ausgeblendete Spalte bleibt in der Liste, so kannst du sie später wieder einblenden.</li><li><em>Überschrift</em> ersetzt den Namen des Attributs in der Tabelle, zum Beispiel <em>Betriebsstatus</em> für <em>Status</em>.</li><li><em>Sortierbar</em> bestimmt, ob Lesende nach der Spalte sortieren dürfen.</li></ul></li><li>Ändere die Reihenfolge, indem du eine Zeile ziehst, oder mit den Pfeil-Buttons einer Zeile.</li><li>Wähle unter <em>Standardsortierung</em> die Spalte und Richtung, nach der die Tabelle sortiert ist, solange niemand eine Sortierung gewählt hat.</li><li>Wähle <em>Speichern</em>. Mindestens eine Spalte muss sichtbar sein.</li></ol><p>Eine Eigenschaft, die dem Entitätstyp nicht mehr zugeordnet ist, erscheint als <em>Nicht verfügbar</em> und wird beim Speichern entfernt. Jede Änderung wird im Audit-Trail festgehalten.</p><p>Über die API ersetzt <code>PUT /catalogs/{id}/columns</code> die Liste. Jede Spalte nennt ein Feld (<code>&quot;field&quot;: &quot;name&quot;</code>, <code>description</code>, <code>externalId</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>entityVersion</code>) oder eine Eigenschaft (<code>&quot;propertyDefId&quot;: &quot;…&quot;</code>), mit <code>displayLabel</code>, <code>visible</code>, <code>sortable</code> und höchstens einer <code>defaultSortDirection</code> (<code>asc</code> oder <code>desc</code>). Eine leere Liste stellt die Standardspalten wieder her.</p>`,7)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};